pub fn canonicalize(value: &Json) -> String {
    match value {
        Json::Null => "null".into(),
        Json::Bool(true) => "true".into(),
        Json::Bool(false) => "false".into(),
        Json::Number(number) => number.to_string(),
        Json::String(text) => escape_string(text),
        Json::Array(items) => {
            let values = items.iter().map(canonicalize).collect::<Vec<_>>();
            format!("[{}]", values.join(","))
        }
        Json::Object(entries) => {
            let mut entries = entries.iter().collect::<Vec<_>>();
            entries.sort_by(|(left, _), (right, _)| {
                left.encode_utf16().cmp(right.encode_utf16())
            });

            let members = entries
                .into_iter()
                .map(|(key, nested)| format!("{}:{}", escape_string(key), canonicalize(nested)))
                .collect::<Vec<_>>();
            format!("{{{}}}", members.join(","))
        }
    }
}

fn escape_string(text: &str) -> String {
    let mut escaped = String::with_capacity(text.len() + 2);
    escaped.push('"');

    for character in text.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\u{08}' => escaped.push_str("\\b"),
            '\u{0c}' => escaped.push_str("\\f"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            character if character <= '\u{1f}' => {
                use std::fmt::Write;
                write!(escaped, "\\u{:04x}", character as u32).expect("writing to String");
            }
            character => escaped.push(character),
        }
    }

    escaped.push('"');
    escaped
}

